#include <bits/stdc++.h>
using namespace std;
typedef pair<int, int> pii;
char gridA[15][15], gridB[15][15];
int delta[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
int nodeIndex[65][15][15];
int maxFlowCap[15][15];
int nodeCounter = 1;

struct Edge {
  int start, end;
  long long capacity, flow;
  Edge() {}
  Edge(int u, int v, long long cap): start(u), end(v), capacity(cap), flow(0) {}
};

struct DinicFlow {
  int totalNodes;
  vector<Edge> edges;
  vector<vector<int>> adj;
  vector<int> level, ptr;

  DinicFlow(int N): totalNodes(N), edges(), adj(N), level(N), ptr(N) {}

  void addEdge(int u, int v, long long cap) {
    if (u != v) {
      edges.emplace_back(Edge(u, v, cap));
      adj[u].push_back(edges.size() - 1);
      edges.emplace_back(Edge(v, u, 0));
      adj[v].push_back(edges.size() - 1);
    }
  }

  bool buildLevelGraph(int S, int T) {
    queue<int> q({S});
    fill(level.begin(), level.end(), totalNodes + 1);
    level[S] = 0;
    while (!q.empty()) {
      int u = q.front(); q.pop();
      if (u == T) break;
      for (int e_idx: adj[u]) {
        Edge &e = edges[e_idx];
        if (e.flow < e.capacity && level[e.v] > level[e.u] + 1) {
          level[e.v] = level[e.u] + 1;
          q.push(e.v);
        }
      }
    }
    return level[T] != totalNodes + 1;
  }

  long long sendFlow(int u, int T, long long flow = -1) {
    if (u == T || flow == 0) return flow;
    for (int &i = ptr[u]; i < (int)adj[u].size(); ++i) {
      Edge &e = edges[adj[u][i]];
      Edge &oe = edges[adj[u][i]^1];
      if (level[e.v] == level[e.u] + 1) {
        long long amt = e.capacity - e.flow;
        if (flow != -1 && amt > flow) amt = flow;
        long long pushed = sendFlow(e.v, T, amt);
        if (pushed > 0) {
          e.flow += pushed;
          oe.flow -= pushed;
          return pushed;
        }
      }
    }
    return 0;
  }

  long long maxFlow(int S, int T) {
    long long totalFlow = 0;
    while (buildLevelGraph(S, T)) {
      fill(ptr.begin(), ptr.end(), 0);
      while (long long flow = sendFlow(S, T))
        totalFlow += flow;
    }
    return totalFlow;
  }
};

int main() {
  memset(maxFlowCap, -1, sizeof(maxFlowCap));
  int n, t;
  scanf("%d%d", &n, &t);
  for (int i=1; i<=n; i++) {
    scanf("%s", gridA[i]+1);
  }
  for (int i=0; i<=t+1; i++) {
    for (int j=1; j<=n; j++) {
      for (int k=1; k<=n; k++) {
        nodeIndex[i][j][k] = nodeCounter++;
      }
    }
  }
  nodeCounter++;
  for (int i=1; i<=n; i++) {
    scanf("%s", gridB[i]+1);
  }
  queue<pii> q;
  for (int i=1; i<=n; i++) {
    for (int j=1; j<=n; j++) {
      if (gridA[i][j] == 'Z') {
        q.push({i, j});
        maxFlowCap[i][j] = 0;
      }
    }
  }
  while (!q.empty()) {
    int y = q.front().first, x = q.front().second;
    q.pop();
    for (int i=0; i<4; i++) {
      int ny = y + delta[i][0], nx = x + delta[i][1];
      if (ny >= 1 && ny <= n && nx >= 1 && nx <= n && gridA[ny][nx] != 'Y' && maxFlowCap[ny][nx] == -1) {
        maxFlowCap[ny][nx] = maxFlowCap[y][x] + 1;
        q.push({ny, nx});
      }
    }
  }
  for (int i=1; i<=n; i++) {
    for (int j=1; j<=n; j++) {
      if (maxFlowCap[i][j] == -1) maxFlowCap[i][j] = 1e9;
      if (maxFlowCap[i][j] > t) maxFlowCap[i][j] = 1e9;
    }
  }
  int s = 0, t_node = nodeCounter - 1;
  DinicFlow network(nodeCounter);
  for (int i=1; i<=n; i++) {
    for (int j=1; j<=n; j++) {
      if (gridA[i][j] >= '1' && gridA[i][j] <= '9') {
        network.addEdge(s, nodeIndex[0][i][j], gridA[i][j]-'0');
      }
    }
  }
  for (int i=1; i<=n; i++) {
    for (int j=1; j<=n; j++) {
      if (gridA[i][j] == 'Y' || gridA[i][j] == 'Z') continue;
      for (int k=0; k<4; k++) {
        int ny = i + delta[k][0], nx = j + delta[k][1];
        if (ny >= 1 && ny <= n && nx >= 1 && nx <= n && gridA[ny][nx] != 'Y' && gridA[ny][nx] != 'Z') {
          for (int x=0; x<t; x++) {
            if (maxFlowCap[ny][nx] >= x+1 && maxFlowCap[i][j] > x) {
              network.addEdge(nodeIndex[x][i][j], nodeIndex[x+1][ny][nx], 1000);
            }
          }
        }
      }
    }
  }
  for (int i=1; i<=n; i++) {
    for (int j=1; j<=n; j++) {
      if (gridA[i][j] == 'Y' || gridA[i][j] == 'Z') continue;
      for (int x=0; x<=t; x++) {
        if (gridB[i][j] >= '1' && gridB[i][j] <= '9') {
          network.addEdge(nodeIndex[x][i][j], nodeIndex[t+1][i][j], gridB[i][j]-'0');
        }
      }
    }
  }
  for (int i=1; i<=n; i++) {
    for (int j=1; j<=n; j++) {
      if (gridA[i][j] == 'Y' || gridA[i][j] == 'Z') continue;
      if (gridB[i][j] >= '1' && gridB[i][j] <= '9') {
        network.addEdge(nodeIndex[t+1][i][j], t_node, gridB[i][j]-'0');
      }
    }
  }
  printf("%lld\n", network.maxFlow(s, t_node));
}
